import{_ as r,y as o,a,o as i,a2 as t,D as s}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Search Engines","description":"","frontmatter":{},"headers":[],"relativePath":"configure/search-engines.md","filePath":"configure/search-engines.md","lastUpdated":1789411722000}'),g={name:"configure/search-engines.md"};function h(c,e,l,d,u,p){const n=o("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="search-engines" tabindex="-1">Search Engines <a class="header-anchor" href="#search-engines" aria-label="Permalink to &quot;Search Engines&quot;">​</a></h1><p>Product search on the storefront and in the admin panel runs on the database by default. For a large catalog, you can connect an Elasticsearch cluster and choose where it is used. The <strong>Search Engines</strong> group is available in Bagisto 2.5.</p><h2 id="choose-the-search-engine" tabindex="-1">Choose the search engine <a class="header-anchor" href="#choose-the-search-engine" aria-label="Permalink to &quot;Choose the search engine&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Search Engines &gt;&gt; General</strong>.</li><li>In <strong>Settings</strong>, switch <strong>Enable External Search Engine</strong> on. <strong>Default Search Engine</strong> appears.</li><li>Choose the <strong>Default Search Engine</strong>: <strong>Database</strong> or <strong>Elasticsearch</strong>.</li><li>In <strong>Products</strong>, choose the <strong>Admin Search Mode</strong>.</li><li>Choose the <strong>Storefront Search Mode</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),s(n,{src:"/images/configure/search-engines-general.png",alt:"General screen of the Search Engines group with the external search engine turned on"}),e[1]||(e[1]=t('<p><strong>Enable External Search Engine:</strong> While it is off, every search runs on the database, whatever the other settings say. It is off by default.</p><p><strong>Default Search Engine:</strong> The engine used wherever a search mode is left on <strong>Use Default</strong>.</p><p><strong>Admin Search Mode:</strong> The engine behind the header search, the data grids and the other searches in the admin panel.</p><p><strong>Storefront Search Mode:</strong> The engine behind category pages, the search page and the other searches on the storefront.</p><p>Each search mode can be <strong>Use Default</strong>, <strong>Database</strong> or <strong>Elasticsearch</strong>, so you can, for example, keep the admin panel on the database while the storefront uses Elasticsearch.</p><h2 id="connect-elasticsearch" tabindex="-1">Connect Elasticsearch <a class="header-anchor" href="#connect-elasticsearch" aria-label="Permalink to &quot;Connect Elasticsearch&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Search Engines &gt;&gt; Elasticsearch</strong>.</li><li>In <strong>Settings</strong>, choose the <strong>Authentication</strong>. Only the fields that method needs are shown.</li><li>Enter the connection details described below.</li><li>Click <strong>Save Configuration</strong>.</li><li>Click <strong>Test Connection</strong> to check that the store can reach the cluster.</li></ol>',7)),s(n,{src:"/images/configure/search-engines-elasticsearch.png",alt:"Elasticsearch screen with username and password authentication"}),e[2]||(e[2]=t('<p><strong>Authentication:</strong> How the store connects to the cluster, and the fields each method needs:</p><ul><li><strong>No authentication</strong> – <strong>Hosts</strong>.</li><li><strong>Username and password</strong> – <strong>Hosts</strong>, <strong>Username</strong> and <strong>Password</strong>.</li><li><strong>API key</strong> – <strong>Hosts</strong> and <strong>API Key</strong>.</li><li><strong>Elastic Cloud with API key</strong> – <strong>Cloud ID</strong> and <strong>API Key</strong>.</li><li><strong>Elastic Cloud with username and password</strong> – <strong>Cloud ID</strong>, <strong>Username</strong> and <strong>Password</strong>.</li></ul><p><strong>Hosts:</strong> Where the cluster is reached, such as <code>http://localhost:9200</code>. Separate several hosts with a comma. Leave it empty to use the value from the server&#39;s environment file.</p><p><strong>Index Prefix:</strong> Added to the front of every index name, so several stores can share one cluster.</p><p><strong>Minimum Query Length</strong> and <strong>Maximum Query Length:</strong> The shortest and longest search term the storefront search box accepts.</p><p>The result of <strong>Test Connection</strong> tells you whether Elasticsearch <strong>is available</strong>, <strong>did not answer</strong>, <strong>rejected the credentials</strong>, answered but <strong>is not a supported Elasticsearch server</strong>, or <strong>is not configured</strong>.</p><h3 id="build-the-index" tabindex="-1">Build the index <a class="header-anchor" href="#build-the-index" aria-label="Permalink to &quot;Build the index&quot;">​</a></h3><p>A cluster only returns products that have been indexed. After connecting it for the first time, ask whoever manages the server to run the product indexer for the search engine. It also runs whenever a product is saved, so the index keeps itself up to date afterwards.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>Bagisto 2.4 has no <strong>Search Engines</strong> group. Its <strong>Search Engine</strong>, <strong>Admin Search Mode</strong> and <strong>Storefront Search Mode</strong> settings, and its <strong>Minimum query length</strong> and <strong>Maximum query length</strong>, are in the <strong>Search</strong> section under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>. The engines to choose from there are <strong>Database</strong> and <strong>Elastic Search</strong>, and the Elasticsearch connection is set in the server&#39;s environment file.</p>',10))])}const _=r(g,[["render",h]]);export{m as __pageData,_ as default};
